package com.zest.products.product;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.test.web.client.TestRestTemplate; import org.springframework.boot.test.web.server.LocalServerPort; import org.springframework.http.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) class ProductApiIntegrationTest { @Autowired TestRestTemplate rest; @LocalServerPort int port; @Test void administratorCanLogInAndReadProducts(){String base="http://localhost:"+port;var login=rest.postForEntity(base+"/api/v1/auth/login",Map.of("username","admin","password","Admin123!"),Map.class);assertEquals(HttpStatus.OK,login.getStatusCode());String access=(String)Objects.requireNonNull(login.getBody()).get("accessToken");HttpHeaders h=new HttpHeaders();h.setBearerAuth(access);var products=rest.exchange(base+"/api/v1/products",HttpMethod.GET,new HttpEntity<>(h),String.class);assertEquals(HttpStatus.OK,products.getStatusCode());} }
